#include "tevox.h"
#include <math.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <strings.h>
static void *grow(void *p,size_t n,size_t w){if(!n)n=1;if(w&&n>SIZE_MAX/w){tv_print_error("allocation overflow");exit(1);}void *q=realloc(p,n*w);if(!q){tv_print_error("out of memory");exit(1);}return q;}
static char *dupstr(const char *s){char *q=strdup(s?s:"");if(!q)exit(1);return q;}
static double clamp(double x,double a,double b){return x<a?a:x>b?b:x;}
static int64_t lo(int64_t a,int64_t b){return a<b?a:b;}static int64_t hi(int64_t a,int64_t b){return a>b?a:b;}
static int64_t ov(int64_t a,int64_t b,int64_t c,int64_t d){int64_t x=hi(a,c),y=lo(b,d);return y>x?y-x:0;}
static TvContig *find_contig(TvGenome *g,const char *n){for(size_t i=0;i<g->n_contigs;i++)if(!strcmp(g->contigs[i].name,n))return &g->contigs[i];return NULL;}
static double nfrac(TvGenome *g,const char *name,int64_t start,int64_t end){TvContig *c=find_contig(g,name);if(!c||!c->line_bases||start<0||end>c->length||end<=start)return 1;FILE *f=fopen(g->fasta_path,"rb");if(!f)return 1;int64_t pos=start,n=0,bad=0;while(pos<end){int64_t row=pos/c->line_bases,col=pos%c->line_bases,take=lo(c->line_bases-col,end-pos),off=c->seq_offset+row*c->line_bytes+col;if(fseeko(f,(off_t)off,SEEK_SET)){fclose(f);return 1;}for(int64_t i=0;i<take;i++){int ch=fgetc(f);if(ch==EOF){fclose(f);return 1;}n++;if(ch=='N'||ch=='n'||ch=='-'||ch=='.')bad++;}pos+=take;}fclose(f);return n?(double)bad/(double)n:1;}
static int cq(char c){return strchr("M=XI",c)!=NULL;}static int ct(char c){return strchr("M=XD",c)!=NULL;}static int both(char c){return strchr("M=X",c)!=NULL;}
static int64_t aligned(const TvPaf *p,int64_t s,int64_t e){int64_t q=p->qstart,n=0;for(size_t i=0;i<p->n_ops;i++){TvCigarOp o=p->ops[i];if(both(o.code))n+=ov(q,q+o.length,s,e);if(cq(o.code))q+=o.length;}return n;}
static int64_t inserted(const TvPaf *p,int64_t s,int64_t e){int64_t q=p->qstart,n=0;for(size_t i=0;i<p->n_ops;i++){TvCigarOp o=p->ops[i];if(o.code=='I')n+=ov(q,q+o.length,s,e);if(cq(o.code))q+=o.length;}return n;}
static double identity(const TvPaf *p,int64_t s,int64_t e){int64_t q=p->qstart,yes=0,no=0,unk=0;for(size_t i=0;i<p->n_ops;i++){TvCigarOp o=p->ops[i];if(both(o.code)){int64_t n=ov(q,q+o.length,s,e);if(o.code=='=')yes+=n;else if(o.code=='X')no+=n;else unk+=n;}if(cq(o.code))q+=o.length;}if(yes+no&&unk==0)return(double)yes/(double)(yes+no);return p->block_len?clamp((double)p->matches/(double)p->block_len,0,1):0;}
static int map_boundary(const TvPaf *p,int64_t x,int64_t *target){if(x<p->qstart||x>p->qend)return 0;int64_t q=p->qstart,t=p->strand=='+'?p->tstart:p->tend;for(size_t i=0;i<p->n_ops;i++){TvCigarOp o=p->ops[i];int64_t qn=q+(cq(o.code)?o.length:0);if(cq(o.code)&&x>=q&&x<=qn){if(both(o.code)){int64_t d=x-q;*target=p->strand=='+'?t+d:t-d;}else *target=t;return 1;}if(cq(o.code))q=qn;if(ct(o.code))t+=p->strand=='+'?o.length:-o.length;}if(x==p->qend){*target=t;return 1;}return 0;}
static int known(const char *f){return f&&*f&&strcmp(f,".")&&strcasecmp(f,"unknown");}
static int same(const TvTE *a,const TvTE *b){return known(a->family)&&known(b->family)&&!strcasecmp(a->family,b->family);}
static int conflict(const TvTE *a,const TvTE *b){return known(a->family)&&known(b->family)&&strcasecmp(a->family,b->family);}
static int node_for(TvRun *r,int g,size_t local){size_t n=0;for(int i=0;i<g;i++)n+=r->genomes[i].n_tes;return(int)(n+local);}
static void push_projection(TvRun *r,TvProjection *p){if(r->n_projections==r->cap_projections){r->cap_projections=r->cap_projections?r->cap_projections*2:256;r->projections=grow(r->projections,r->cap_projections,sizeof(*r->projections));}r->projections[r->n_projections++]=*p;}
static int bpdist(const TvProjection *p,const TvTE *t){int64_t d=llabs(p->start-t->start)+llabs(p->end-t->end);return d>INT32_MAX?INT32_MAX:(int)d;}
static double candidate_score(TvRun *r,const TvTE *s,const TvTE *t,const TvProjection *p){int64_t pl=hi(1,p->end-p->start),tl=t->end-t->start,x=ov(p->start,p->end,t->start,t->end);double ro=fmin((double)x/(double)pl,(double)x/(double)tl),boundary=1-clamp((double)bpdist(p,t)/(double)(2*r->cfg.candidate_window+1),0,1),fam=same(s,t)?1:conflict(s,t)?-1:.25;return clamp(25*fmin(p->left_flank,p->right_flank)+20*p->identity+20*ro+15*boundary+10*clamp(p->mapq/60.0,0,1)+10*fam,0,100);}
static TvProjection evaluate(TvRun *r,int source,int target,int pi){TvTE *s=&r->nodes[source];TvPaf *p=&r->pafs[pi];TvProjection z={.source_te=source,.target_genome=target,.paf_index=pi,.state=TV_UNCALLABLE,.target_te=-1,.contig=dupstr(p->tname)};TvContig *qc=find_contig(&r->genomes[s->genome],s->contig);if(!qc){snprintf(z.evidence,sizeof(z.evidence),"SOURCE_CONTIG_NOT_INDEXED");return z;}int f=r->cfg.flank;int64_t ls=hi(0,s->start-f),re=lo(qc->length,s->end+f),ll=s->start-ls,rl=re-s->end;z.left_flank=ll?(double)aligned(p,ls,s->start)/(double)ll:1;z.right_flank=rl?(double)aligned(p,s->end,re)/(double)rl:1;z.left_flank=clamp(z.left_flank,0,1);z.right_flank=clamp(z.right_flank,0,1);z.identity=identity(p,ls,re);z.mapq=p->mapq;int64_t a,b;if(!map_boundary(p,s->start,&a)||!map_boundary(p,s->end,&b)){snprintf(z.evidence,sizeof(z.evidence),"TE_BOUNDARY_UNMAPPED");return z;}z.start=lo(a,b);z.end=hi(a,b);TvContig *tc=find_contig(&r->genomes[target],z.contig);if(!tc){snprintf(z.evidence,sizeof(z.evidence),"TARGET_CONTIG_NOT_INDEXED");return z;}int64_t ns=hi(0,z.start-(z.start==z.end?10:0)),ne=lo(tc->length,z.end+(z.start==z.end?10:0));if(ne<=ns)ne=lo(tc->length,ns+1);z.n_fraction=nfrac(&r->genomes[target],z.contig,ns,ne);double flank=fmin(z.left_flank,z.right_flank);z.quality=clamp(100*(.35*flank+.25*z.identity+.15*clamp(z.mapq/60.0,0,1)+.15*(1-z.n_fraction)+.10),0,100);double best=-1,second=-1;for(size_t i=0;i<r->genomes[target].n_tes;i++){TvTE *t=&r->genomes[target].tes[i];if(strcmp(t->contig,z.contig)||t->end<z.start-r->cfg.candidate_window||t->start>z.end+r->cfg.candidate_window)continue;z.candidate_count++;double score=candidate_score(r,s,t,&z);if(score>best){second=best;best=score;z.target_te=node_for(r,target,i);}else if(score>second)second=score;}double ins=(double)inserted(p,s->start,s->end)/(double)(s->end-s->start);if(p->mapq<r->cfg.min_mapq||flank<r->cfg.min_flank_fraction){z.state=TV_UNCALLABLE;z.quality*=.6;snprintf(z.evidence,sizeof(z.evidence),"LOW_MAPPING_OR_FLANK_SUPPORT");}else if(z.n_fraction>r->cfg.max_n_fraction){z.state=TV_ASSEMBLY_GAP;z.quality*=.7;snprintf(z.evidence,sizeof(z.evidence),"TARGET_SEQUENCE_GAP");}else if(z.target_te>=0&&second>=best-5){z.state=TV_PROJECTION_AMBIGUOUS;z.quality*=.75;snprintf(z.evidence,sizeof(z.evidence),"MULTIPLE_NEAR_TIE_CANDIDATES");}else if(z.target_te>=0){TvTE *t=&r->nodes[z.target_te];if(conflict(s,t)){z.state=TV_FAMILY_OR_BOUNDARY_DISCORDANCE;z.quality*=.8;snprintf(z.evidence,sizeof(z.evidence),"ANNOTATED_FAMILY_CONFLICT");}else{z.state=TV_PRESENT_ANNOTATED;snprintf(z.evidence,sizeof(z.evidence),"ANNOTATED_LOCUS_MATCH");}}else if(ins>=.7){z.state=TV_EMPTY_SITE_CONFIRMED;snprintf(z.evidence,sizeof(z.evidence),"TE_SPANS_QUERY_INSERTION");}else if((double)(z.end-z.start)>=(double)(s->end-s->start)*.5){z.state=TV_PRESENT_UNANNOTATED;snprintf(z.evidence,sizeof(z.evidence),"ALIGNED_SEQUENCE_WITHOUT_ANNOTATION");}else{z.state=TV_STRUCTURAL_ALTERNATIVE;z.quality*=.8;snprintf(z.evidence,sizeof(z.evidence),"NON_INSERTION_LENGTH_CHANGE");}return z;}
static void projections(TvRun *r){for(size_t s=0;s<r->n_nodes;s++){TvTE *te=&r->nodes[s];for(size_t t=0;t<r->n_genomes;t++){if((int)t==te->genome)continue;TvProjection best={.source_te=(int)s,.target_genome=(int)t,.paf_index=-1,.state=TV_UNCALLABLE,.target_te=-1,.contig=dupstr(".")},second={0};int hb=0,hs=0;for(size_t p=0;p<r->n_pafs;p++){TvPaf *pa=&r->pafs[p];if(pa->query_genome!=te->genome||pa->target_genome!=(int)t||strcmp(pa->qname,te->contig)||pa->qend<=te->start||pa->qstart>=te->end)continue;TvProjection c=evaluate(r,(int)s,(int)t,(int)p);if(!hb||c.quality>best.quality){if(hs)free(second.contig);if(hb){second=best;hs=1;}else free(best.contig);best=c;hb=1;}else if(!hs||c.quality>second.quality){if(hs)free(second.contig);second=c;hs=1;}else free(c.contig);}if(!hb)snprintf(best.evidence,sizeof(best.evidence),"NO_SPANNING_ALIGNMENT");else if(hs&&second.quality>=best.quality-5&&(strcmp(second.contig,best.contig)||llabs(second.start-best.start)>r->cfg.candidate_window)){best.state=TV_PROJECTION_AMBIGUOUS;best.quality*=.75;snprintf(best.evidence,sizeof(best.evidence),"MULTIPLE_NEAR_TIE_PROJECTIONS");}if(hs)free(second.contig);push_projection(r,&best);}}}
static void edge(TvRun *r,int a,int b,double score,int compatible,int d){if(a==b)return;int x=a<b?a:b,y=a<b?b:a;for(size_t i=0;i<r->n_edges;i++)if(r->edges[i].a==x&&r->edges[i].b==y){r->edges[i].reciprocal=true;if(score>r->edges[i].score){r->edges[i].score=score;r->edges[i].family_match=compatible;r->edges[i].breakpoint_distance=d;}return;}if(r->n_edges==r->cap_edges){r->cap_edges=r->cap_edges?r->cap_edges*2:256;r->edges=grow(r->edges,r->cap_edges,sizeof(*r->edges));}r->edges[r->n_edges++]=(TvEdge){.a=x,.b=y,.score=score,.family_match=compatible,.breakpoint_distance=d};}
static void edges(TvRun *r){for(size_t i=0;i<r->n_projections;i++){TvProjection *p=&r->projections[i];if(p->target_te<0||(p->state!=TV_PRESENT_ANNOTATED&&p->state!=TV_FAMILY_OR_BOUNDARY_DISCORDANCE&&p->state!=TV_PROJECTION_AMBIGUOUS))continue;TvTE *s=&r->nodes[p->source_te];int g=p->target_genome;for(size_t j=0;j<r->genomes[g].n_tes;j++){TvTE *t=&r->genomes[g].tes[j];if(strcmp(t->contig,p->contig)||t->end<p->start-r->cfg.candidate_window||t->start>p->end+r->cfg.candidate_window)continue;edge(r,p->source_te,node_for(r,g,j),candidate_score(r,s,t,p),!conflict(s,t),bpdist(p,t));}}for(size_t i=0;i<r->n_edges;i++)if(r->edges[i].reciprocal)r->edges[i].score=clamp(r->edges[i].score+5,0,100);}
static int root(int *p,int x){if(p[x]!=x)p[x]=root(p,p[x]);return p[x];}
static int quota(TvRun *r,int *p,int a,int b){for(size_t g=0;g<r->n_genomes;g++){int n=0;for(size_t i=0;i<r->n_nodes;i++){int x=root(p,(int)i);if((x==a||x==b)&&r->nodes[i].genome==(int)g)n++;}if(n>r->genomes[g].max_locus_copies)return 0;}return 1;}
static void select_graph(TvRun *r){int *p=grow(NULL,r->n_nodes,sizeof(*p)),*rank=calloc(r->n_nodes,sizeof(*rank)),*order=grow(NULL,r->n_edges,sizeof(*order));if(!rank)exit(1);for(size_t i=0;i<r->n_nodes;i++)p[i]=(int)i;for(size_t i=0;i<r->n_edges;i++)order[i]=(int)i;for(size_t i=1;i<r->n_edges;i++){int v=order[i];size_t j=i;while(j&&(r->edges[order[j-1]].score<r->edges[v].score||(r->edges[order[j-1]].score==r->edges[v].score&&order[j-1]>v))){order[j]=order[j-1];j--;}order[j]=v;}for(size_t i=0;i<r->n_edges;i++){TvEdge *e=&r->edges[order[i]];if(e->score<r->cfg.min_edge_score||!e->family_match)continue;int a=root(p,e->a),b=root(p,e->b);if(a==b){e->selected=true;continue;}if(!quota(r,p,a,b))continue;if(rank[a]<rank[b])p[a]=b;else{p[b]=a;if(rank[a]==rank[b])rank[a]++;}e->selected=true;}int *map=grow(NULL,r->n_nodes,sizeof(*map));for(size_t i=0;i<r->n_nodes;i++)map[i]=-1;r->components=grow(NULL,r->n_nodes,sizeof(*r->components));r->n_loci=0;for(size_t i=0;i<r->n_nodes;i++){int x=root(p,(int)i);if(map[x]<0)map[x]=r->n_loci++;r->components[i]=map[x];}free(map);free(order);free(rank);free(p);}
int tv_analyze(TvRun *r){if(r->n_genomes<2||!r->n_pafs||r->nodes){tv_print_error("analysis requires genomes/alignments and runs once");return -1;}for(size_t g=0;g<r->n_genomes;g++){if(r->n_nodes>SIZE_MAX-r->genomes[g].n_tes)return -1;r->n_nodes+=r->genomes[g].n_tes;}if(!r->n_nodes)return -1;r->nodes=grow(NULL,r->n_nodes,sizeof(*r->nodes));size_t n=0;for(size_t g=0;g<r->n_genomes;g++)for(size_t t=0;t<r->genomes[g].n_tes;t++)r->nodes[n++]=r->genomes[g].tes[t];projections(r);edges(r);select_graph(r);if(r->cfg.verbose)fprintf(stderr,"tevox: %zu TEs, %zu projections, %zu edges, %d loci\n",r->n_nodes,r->n_projections,r->n_edges,r->n_loci);return 0;}
